-- SQL Schema for database `lms1`
-- Refactored & Optimized (Removed circular/redundant foreign key loops)

CREATE DATABASE IF NOT EXISTS `lms1` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `lms1`;

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Table: cau_hinh_he_thong
DROP TABLE IF EXISTS `cau_hinh_he_thong`;
CREATE TABLE `cau_hinh_he_thong` (
  `cau_hinh_id` SMALLINT NOT NULL DEFAULT 1,
  `ten_truong` VARCHAR(200) NOT NULL,
  `logo_url` VARCHAR(500) DEFAULT NULL,
  `dia_chi` TEXT DEFAULT NULL,
  `hotline` VARCHAR(20) DEFAULT NULL,
  `email_lien_he` VARCHAR(150) DEFAULT NULL,
  `hoc_ky_hien_tai_id` INT NOT NULL,
  PRIMARY KEY (`cau_hinh_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 2. Table: invalidated_token
DROP TABLE IF EXISTS `invalidated_token`;
CREATE TABLE `invalidated_token` (
  `id` VARCHAR(255) NOT NULL,
  `expiry_time` DATETIME(6) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 3. Table: nam_hoc
DROP TABLE IF EXISTS `nam_hoc`;
CREATE TABLE `nam_hoc` (
  `nam_hoc_id` INT NOT NULL AUTO_INCREMENT,
  `ten_nam_hoc` VARCHAR(20) NOT NULL,
  `ngay_bat_dau` DATE DEFAULT NULL,
  `ngay_ket_thuc` DATE DEFAULT NULL,
  PRIMARY KEY (`nam_hoc_id`),
  UNIQUE KEY `uk_nam_hoc_ten` (`ten_nam_hoc`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 4. Table: hoc_ky
DROP TABLE IF EXISTS `hoc_ky`;
CREATE TABLE `hoc_ky` (
  `hoc_ky_id` INT NOT NULL AUTO_INCREMENT,
  `nam_hoc_id` INT NOT NULL,
  `so_hoc_ky` SMALLINT NOT NULL,
  PRIMARY KEY (`hoc_ky_id`),
  UNIQUE KEY `uk_hoc_ky_nam_so` (`nam_hoc_id`, `so_hoc_ky`),
  CONSTRAINT `fk_hoc_ky_nam_hoc` FOREIGN KEY (`nam_hoc_id`) REFERENCES `nam_hoc` (`nam_hoc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Add FK for cau_hinh_he_thong after hoc_ky exists
ALTER TABLE `cau_hinh_he_thong` ADD CONSTRAINT `fk_cau_hinh_hoc_ky` FOREIGN KEY (`hoc_ky_hien_tai_id`) REFERENCES `hoc_ky` (`hoc_ky_id`);

-- 5. Table: nguoi_dung
DROP TABLE IF EXISTS `nguoi_dung`;
CREATE TABLE `nguoi_dung` (
  `nguoi_dung_id` VARCHAR(36) NOT NULL,
  `ten_dang_nhap` VARCHAR(100) NOT NULL,
  `mat_khau_hash` VARCHAR(255) NOT NULL,
  `vai_tro` VARCHAR(50) NOT NULL,
  `trang_thai` VARCHAR(50) NOT NULL,
  `email` VARCHAR(150) DEFAULT NULL,
  `so_dien_thoai` VARCHAR(15) DEFAULT NULL,
  `bat_buoc_doi_mk` BIT(1) NOT NULL DEFAULT b'0',
  `lan_dang_nhap_cuoi` DATETIME DEFAULT NULL,
  `ngay_tao` DATETIME NOT NULL,
  `ngay_cap_nhat` DATETIME NOT NULL,
  PRIMARY KEY (`nguoi_dung_id`),
  UNIQUE KEY `uk_nguoi_dung_ten_dn` (`ten_dang_nhap`),
  UNIQUE KEY `uk_nguoi_dung_email` (`email`),
  UNIQUE KEY `uk_nguoi_dung_sdt` (`so_dien_thoai`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 6. Table: ho_so_giao_vien
DROP TABLE IF EXISTS `ho_so_giao_vien`;
CREATE TABLE `ho_so_giao_vien` (
  `giao_vien_id` BIGINT NOT NULL AUTO_INCREMENT,
  `nguoi_dung_id` VARCHAR(36) NOT NULL,
  `ma_giao_vien` VARCHAR(30) NOT NULL,
  `ho_ten` VARCHAR(100) NOT NULL,
  `bo_mon` VARCHAR(100) DEFAULT NULL,
  `ngay_sinh` DATE DEFAULT NULL,
  `gioi_tinh` VARCHAR(20) DEFAULT NULL,
  PRIMARY KEY (`giao_vien_id`),
  UNIQUE KEY `uk_giao_vien_nguoi_dung` (`nguoi_dung_id`),
  UNIQUE KEY `uk_giao_vien_ma` (`ma_giao_vien`),
  CONSTRAINT `fk_giao_vien_nguoi_dung` FOREIGN KEY (`nguoi_dung_id`) REFERENCES `nguoi_dung` (`nguoi_dung_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 7. Table: ho_so_phu_huynh
DROP TABLE IF EXISTS `ho_so_phu_huynh`;
CREATE TABLE `ho_so_phu_huynh` (
  `phu_huynh_id` BIGINT NOT NULL AUTO_INCREMENT,
  `nguoi_dung_id` VARCHAR(36) NOT NULL,
  `ho_ten` VARCHAR(100) NOT NULL,
  `email_nhan_thong_bao` VARCHAR(150) DEFAULT NULL,
  PRIMARY KEY (`phu_huynh_id`),
  UNIQUE KEY `uk_phu_huynh_nguoi_dung` (`nguoi_dung_id`),
  CONSTRAINT `fk_phu_huynh_nguoi_dung` FOREIGN KEY (`nguoi_dung_id`) REFERENCES `nguoi_dung` (`nguoi_dung_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 8. Table: mon_hoc
DROP TABLE IF EXISTS `mon_hoc`;
CREATE TABLE `mon_hoc` (
  `mon_hoc_id` SMALLINT NOT NULL AUTO_INCREMENT,
