  `trang_thai` VARCHAR(50) NOT NULL,
  PRIMARY KEY (`lop_hoc_id`),
  UNIQUE KEY `uk_lop_hoc_ten_khoi_nam` (`ten_lop`, `khoi_lop`, `nam_hoc_id`),
  CONSTRAINT `fk_lop_hoc_nam_hoc` FOREIGN KEY (`nam_hoc_id`) REFERENCES `nam_hoc` (`nam_hoc_id`),
  CONSTRAINT `fk_lop_hoc_gv_cn` FOREIGN KEY (`giao_vien_chu_nhiem_id`) REFERENCES `ho_so_giao_vien` (`giao_vien_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 10. Table: ho_so_hoc_sinh
DROP TABLE IF EXISTS `ho_so_hoc_sinh`;
CREATE TABLE `ho_so_hoc_sinh` (
  `hoc_sinh_id` BIGINT NOT NULL AUTO_INCREMENT,
