  PRIMARY KEY (`hoc_sinh_id`),
  UNIQUE KEY `uk_hoc_sinh_nguoi_dung` (`nguoi_dung_id`),
  UNIQUE KEY `uk_hoc_sinh_ma` (`ma_hoc_sinh`),
  CONSTRAINT `fk_hoc_sinh_nguoi_dung` FOREIGN KEY (`nguoi_dung_id`) REFERENCES `nguoi_dung` (`nguoi_dung_id`),
  CONSTRAINT `fk_hoc_sinh_lop_hoc` FOREIGN KEY (`lop_hoc_id`) REFERENCES `lop_hoc` (`lop_hoc_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 11. Table: phu_huynh_hoc_sinh
DROP TABLE IF EXISTS `phu_huynh_hoc_sinh`;
CREATE TABLE `phu_huynh_hoc_sinh` (
  `lien_ket_id` BIGINT NOT NULL AUTO_INCREMENT,
