  UNIQUE KEY `uk_phu_huynh_hoc_sinh` (`phu_huynh_id`, `hoc_sinh_id`),
  CONSTRAINT `fk_ph_hs_phu_huynh` FOREIGN KEY (`phu_huynh_id`) REFERENCES `ho_so_phu_huynh` (`phu_huynh_id`),
  CONSTRAINT `fk_ph_hs_hoc_sinh` FOREIGN KEY (`hoc_sinh_id`) REFERENCES `ho_so_hoc_sinh` (`hoc_sinh_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 12. Table: phan_cong_giang_day
DROP TABLE IF EXISTS `phan_cong_giang_day`;
CREATE TABLE `phan_cong_giang_day` (
  `phan_cong_id` BIGINT NOT NULL AUTO_INCREMENT,
